// Water UI - validate the MQTT payload, derive statuses, emit 3 messages.
// Rule 6: parseFloat()/parseInt() before anything reaches InfluxDB.
const p = msg.payload || {};
const boardID = String(p.boardID || p.board_id || '').trim();
const pH = parseFloat(p.pH);
const turbidity = parseFloat(p.turbidity);
const batt_voltage = parseFloat(p.batt_voltage);
const rssi = parseInt(p.rssi, 10);

// Validation: never write NaN or undefined into InfluxDB - it breaks Chart.js.
const missing = [];
if (!boardID) { missing.push('boardID'); }
if (!Number.isFinite(pH)) { missing.push('pH'); }
if (!Number.isFinite(turbidity)) { missing.push('turbidity'); }
if (missing.length > 0) {
    node.warn('Water UI: dropped payload - invalid or missing: ' + missing.join(', '));
    return [null, null, null];
}

// Derived statuses. Single source of truth: MASTER_CONTEXT.md section 5.3
let wq_status = 'Safe';
if (pH < 6.5 || pH > 8.5 || turbidity > 5.0) {
    wq_status = 'Unsafe';
} else if (pH < 7.0 || pH > 8.0 || turbidity > 3.0) {
    wq_status = 'Acceptable';
}

let batt_level = 'Full';
if (batt_voltage <= 3.3) { batt_level = 'Critical'; }
else if (batt_voltage <= 3.5) { batt_level = 'Low'; }
else if (batt_voltage <= 3.7) { batt_level = 'Medium'; }

let wifi_status = 'Excellent';
if (rssi <= -80) { wifi_status = 'Poor'; }
else if (rssi <= -70) { wifi_status = 'Fair'; }
else if (rssi <= -60) { wifi_status = 'Good'; }

// Edge timestamp: the device's epoch-ms 'ts' when present, else arrival time.
const tsMs = Math.floor(Number.isFinite(parseFloat(p.ts)) ? parseFloat(p.ts) : Date.now());

const reading = {
    boardID: boardID,
    pH: pH,
    turbidity: turbidity,
    batt_voltage: Number.isFinite(batt_voltage) ? batt_voltage : 0,
    rssi: Number.isFinite(rssi) ? rssi : 0,
    wq_status: wq_status,
    batt_level: batt_level,
    wifi_status: wifi_status,
    time: new Date(tsMs).toISOString()
};

// --- 1. InfluxDB: line protocol. Tags are indexed, rssi stays an integer. ---
// Build the backslash without embedding one, so this string stays JSON-safe.
const BS = String.fromCharCode(92);
const esc = function (v) { return String(v).replace(/([ ,=])/g, BS + '$1'); };
const tagSet = 'board_id=' + esc(boardID) + ',wq_status=' + esc(wq_status) + ',batt_level=' + esc(batt_level) + ',wifi_status=' + esc(wifi_status);
const fieldSet = 'pH=' + pH + ',turbidity=' + turbidity + ',batt_voltage=' + reading.batt_voltage + ',rssi=' + reading.rssi + 'i';
// ms -> ns as a string: no 2^53 precision loss on the timestamp.
const timeNs = String(tsMs) + '000000';
const influxMsg = {
    payload: 'water_quality,' + tagSet + ' ' + fieldSet + ' ' + timeNs,
    url: env.get('INFLUX_URL', 'http://influxdb:8086') + '/api/v2/write?org=' + encodeURIComponent(env.get('INFLUX_ORG', 'water_ui_org')) + '&bucket=' + encodeURIComponent(env.get('INFLUX_BUCKET', 'water_quality_bucket')) + '&precision=ns',
    method: 'POST',
    headers: {
        'Authorization': 'Token ' + env.get('INFLUX_TOKEN', ''),
        'Content-Type': 'text/plain; charset=utf-8'
    }
};

// --- 2. Notify the Express API so it can push the reading over Socket.io ---
const backendMsg = {
    payload: JSON.stringify(reading),
    url: env.get('BACKEND_URL', 'http://backend:5000') + '/api/internal/sensor-update',
    method: 'POST',
    headers: { 'Content-Type': 'application/json' }
};

// --- 3. Alert branch: the switch node filters wq_status == 'Unsafe' --------
const alertMsg = { payload: Object.assign({}, reading, { chatId: env.get('TELEGRAM_CHAT_ID', ''), type: 'message', content: '' }), reading: reading };

return [influxMsg, backendMsg, alertMsg];
